alternative.css:
[data-ods="select"],
[data-ods="combobox"] {
  display: block;
  width: auto;
  max-width: none;
}

[data-ods="clipboard"],
[data-ods="phone-number"],
[data-ods="textarea"],
[data-ods="timepicker"],
div:has(> input[data-ods="input"]) {
  width: auto;
  max-width: none;
}

html:root {
  --ods-semantic-font-family-body: 'Source Sans Pro', 'Source Sans 3', 'Trebuchet MS', arial, 'Segoe UI', sans-serif;
  --ods-semantic-font-family-heading: 'Source Sans Pro', 'Source Sans 3', 'Trebuchet MS', arial, 'Segoe UI', sans-serif;
}
